#!/usr/bin/env node

import { readFile, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { format } from "prettier";

import { CONSENT_RUNTIME_MODEL as model } from "../../packages/core/protocol/consent-runtime.model.mjs";

const repositoryRoot = resolve(
  dirname(fileURLToPath(import.meta.url)),
  "../..",
);
const generatedHeader =
  "/* This file is generated by scripts/phase4/generate-consent-runtime.mjs. */\n";

const requiredDomainActions = [
  "record-consent-decision",
  "diff-decisions",
  "create-consent-event-batch",
  "withdraw-consent",
  "resolve-effective-access",
];
const requiredApplicationActions = [
  "persist-grant",
  "persist-denial",
  "project-conservative-failure",
  "execute-grant-transition",
  "execute-denial-transition",
  "project-consent-runtime",
  "project-runtime-transition",
  "execute-runtime-decision",
  "execute-runtime-withdrawal",
];
const requiredPendingGrantActions = [
  "create-activation-descriptor",
  "resume",
  "activate",
  "prepare",
  "stage",
  "refresh",
  "restage",
  "stage-restored",
];
const requiredCoordinatorActions = [
  "initialize",
  "decide",
  "retry-pending-grant",
  "refresh-expiry",
  "withdraw",
  "execute-terminal-program",
  "complete-grant",
  "correct-grant",
  "publish-snapshot",
  "open-preferences",
  "close-preferences",
  "subscribe",
  "reserve-terminal-capability",
  "close-terminal-capability",
];
const requiredGeneratedLayers = new Set(
  [
    [
      "record-consent-decision",
      "packages/core/src/domain/consent-decisioning/record-decision.ts",
      "packages/core/protocol/templates/domain/consent-decisioning/record-decision.ts.txt",
    ],
    [
      "diff-consent-decisions",
      "packages/core/src/domain/consent-decisioning/diff-decisions.ts",
      "packages/core/protocol/templates/domain/consent-decisioning/diff-decisions.ts.txt",
    ],
    [
      "create-consent-events",
      "packages/core/src/domain/consent-decisioning/consent-events.ts",
      "packages/core/protocol/templates/domain/consent-decisioning/consent-events.ts.txt",
    ],
    [
      "withdraw-consent",
      "packages/core/src/domain/consent-decisioning/withdraw-consent.ts",
      "packages/core/protocol/templates/domain/consent-decisioning/withdraw-consent.ts.txt",
    ],
    [
      "resolve-effective-access",
      "packages/core/src/domain/terminal-enforcement/resolve-effective-access.ts",
      "packages/core/protocol/templates/domain/terminal-enforcement/resolve-effective-access.ts.txt",
    ],
    [
      "persist-grant",
      "packages/core/src/application/persistence/persist-grant.ts",
      "packages/core/protocol/templates/application/persistence/persist-grant.ts.txt",
    ],
    [
      "persist-denial",
      "packages/core/src/application/persistence/persist-denial.ts",
      "packages/core/protocol/templates/application/persistence/persist-denial.ts.txt",
    ],
    [
      "project-conservative-failure",
      "packages/core/src/application/persistence/conservative-projection.ts",
      "packages/core/protocol/templates/application/persistence/conservative-projection.ts.txt",
    ],
    [
      "execute-grant-transition",
      "packages/core/src/application/transitions/execute-grant-transition.ts",
      "packages/core/protocol/templates/application/transitions/execute-grant-transition.ts.txt",
    ],
    [
      "execute-denial-transition",
      "packages/core/src/application/transitions/execute-denial-transition.ts",
      "packages/core/protocol/templates/application/transitions/execute-denial-transition.ts.txt",
    ],
    [
      "project-consent-runtime",
      "packages/core/src/application/runtime/project-consent-runtime-kernel.ts",
      "packages/core/protocol/templates/application/runtime/project-consent-runtime-kernel.ts.txt",
    ],
    [
      "project-runtime-transition",
      "packages/core/src/application/runtime/consent-runtime-transition-projection-kernel.ts",
      "packages/core/protocol/templates/application/runtime/consent-runtime-transition-projection-kernel.ts.txt",
    ],
    [
      "execute-runtime-decision",
      "packages/core/src/application/runtime/execute-consent-runtime-decision-kernel.ts",
      "packages/core/protocol/templates/application/runtime/execute-consent-runtime-decision-kernel.ts.txt",
    ],
    [
      "execute-runtime-withdrawal",
      "packages/core/src/application/runtime/execute-consent-runtime-withdrawal-kernel.ts",
      "packages/core/protocol/templates/application/runtime/execute-consent-runtime-withdrawal-kernel.ts.txt",
    ],
    [
      "open-cookie-coordinator",
      "packages/core/src/application/runtime/create-open-cookie-kernel.ts",
      "packages/core/protocol/templates/create-open-cookie-kernel.ts.txt",
    ],
  ].map((layer) => JSON.stringify(layer)),
);

function containsEvery(actual, required) {
  return required.every((value) => actual.includes(value));
}

if (
  model.schemaVersion !== 1 ||
  !containsEvery(model.domainActions, requiredDomainActions) ||
  !containsEvery(model.applicationActions, requiredApplicationActions) ||
  !containsEvery(model.pendingGrantActions, requiredPendingGrantActions) ||
  !containsEvery(model.coordinatorActions, requiredCoordinatorActions) ||
  new Set(model.blockReasonOrder).size !== model.blockReasonOrder.length ||
  new Set(model.decisionMethods).size !== model.decisionMethods.length ||
  model.transitionEffects.grant.join(",") !==
    "persist,commit,broadcast,reconcile,receipt,notify" ||
  model.terminalInterpreter.owner.layer !== "execute-denial-transition" ||
  model.terminalInterpreter.owner.symbol !== "executeDenialTransitionProgram" ||
  model.terminalInterpreter.programs.ordinary.join(",") !==
    "commit-pending,broadcast,reconcile,persist,receipt,notify-final" ||
  model.terminalInterpreter.programs.superseding.join(",") !==
    "persist,settle-grants,broadcast,reconcile,receipt,publish" ||
  model.coordinatorProtocol.grant.join(",") !==
    "broadcast,activate,reconcile,aftercare,publish" ||
  model.coordinatorProtocol.expiry.join(",") !== "reconcile,broadcast" ||
  model.generatedLayers.length !== requiredGeneratedLayers.size ||
  new Set(model.generatedLayers.map(({ name }) => name)).size !==
    model.generatedLayers.length ||
  new Set(model.generatedLayers.map(({ output }) => output)).size !==
    model.generatedLayers.length ||
  model.generatedLayers.some(
    ({ name, output, template }) =>
      !requiredGeneratedLayers.has(JSON.stringify([name, output, template])),
  )
) {
  throw new Error("Invalid generated consent-runtime model.");
}

const generatedLayers = [];
for (const { name, output, template } of model.generatedLayers) {
  const outputPath = resolve(repositoryRoot, output);
  const templateSource = await readFile(
    resolve(repositoryRoot, template),
    "utf8",
  );
  const instantiatedSource = templateSource
    .replaceAll(
      "__TERMINAL_PROGRAMS__",
      JSON.stringify(model.terminalInterpreter.programs),
    )
    .replaceAll(
      "__GRANT_STEPS__",
      JSON.stringify(model.coordinatorProtocol.grant),
    )
    .replaceAll(
      "__EXPIRY_STEPS__",
      JSON.stringify(model.coordinatorProtocol.expiry),
    );
  generatedLayers.push(
    Object.freeze({
      name,
      outputPath,
      source: await format(
        `${generatedHeader}${instantiatedSource.replaceAll("\r\n", "\n")}`,
        { filepath: outputPath, parser: "typescript" },
      ),
    }),
  );
}

if (process.argv.includes("--check")) {
  for (const layer of generatedLayers) {
    const existing = await readFile(layer.outputPath, "utf8");
    if (existing !== layer.source) {
      throw new Error(
        `Generated ${layer.name} output is stale: ${layer.outputPath}`,
      );
    }
  }
} else {
  for (const layer of generatedLayers) {
    await writeFile(layer.outputPath, layer.source);
  }
}
